import { getRequestExecutionContext, runWithExecutionContext } from "../shims/request-context.js";
import { createWorkerRevalidationContext } from "./worker-revalidation-context.js";
import { createAppRscRequestHandler } from "./app-rsc-handler.js";
import { resolveSrvxMiddlewareOrigin } from "./srvx-middleware-origin.js";
//#region src/server/app-rsc-combined-handler.ts
/** Combined request/response handler used by default single-stage App entries. */
function createAppRscHandler(options) {
	const appRscRequestHandler = createAppRscRequestHandler(options);
	const appRscHandler = (request, ctx, ...rest) => {
		if (ctx != null || getRequestExecutionContext()) return appRscRequestHandler(request, ctx, ...rest);
		const executionContext = createWorkerRevalidationContext({ middlewareOrigin: resolveSrvxMiddlewareOrigin(request) }, (internalRequest, internalCtx) => runWithExecutionContext(internalCtx, () => appRscRequestHandler(internalRequest, internalCtx)), "node");
		return runWithExecutionContext(executionContext, () => appRscRequestHandler(request, ctx, ...rest));
	};
	return Object.assign(appRscHandler, { handleResponseStage(request, ctx, props, stageOptions) {
		return import("./app-rsc-response-stage.js").then(({ renderAppWorkerResponseStage }) => renderAppWorkerResponseStage(options, request, ctx, props, stageOptions));
	} });
}
//#endregion
export { createAppRscHandler };
